-- THE CITY – migration 004: circular master plan (J Enterprise hub, ring + radial roads, nine market districts).
-- Run after 001–003. Idempotent. Re-seeds the base city from the same generator the app uses (src/lib/city.ts).
--
--  • Adds ring-road support (city_roads.kind) and drops the old axis-aligned-only road constraint.
--  • Replaces the old grid layout. Plots that have USER-OWNED stores are NOT deleted: they are moved into a
--    "Legacy yard" south of the city (region LEGACY) so no ownership data is lost. Use Admin → Plot → Relocate to
--    move those buildings onto new market plots.
--  • Markets are empty land. Only J Enterprise and the nine buildings around it are pre-built.
--  • Adds server-side validation: plots may not overlap other plots or road segments (checked by the database).

-- ───────────── schema ─────────────
do $$ declare c text; begin
  for c in select conname from pg_constraint where conrelid = 'public.city_roads'::regclass and contype = 'c' and pg_get_constraintdef(oid) like '%x0 = x1%' loop
    execute format('alter table public.city_roads drop constraint %I', c);
  end loop;
end $$;
alter table public.city_roads add column if not exists kind text not null default 'seg';
alter table public.city_roads drop constraint if exists city_roads_kind_ok;
alter table public.city_roads add constraint city_roads_kind_ok check (kind in ('seg', 'ring'));
drop trigger if exists city_plots_validate on public.city_plots;
drop trigger if exists city_roads_validate on public.city_roads;

-- ───────────── retire the old layout (keeping user-owned stores) ─────────────
with keep as (
  select p.id, row_number() over (order by p.id) as rn from public.city_plots p
  where p.id <> 'J01' and exists (select 1 from public.stores s where s.plot_id = p.id and s.owner_id is not null)
)
update public.city_plots p set region = 'LEGACY', status = 'reserved', x = -250 + (keep.rn - 1) * 18, z = 440, rot = 0
from keep where p.id = keep.id;
delete from public.city_plots where region is distinct from 'LEGACY' and id <> 'J01';
delete from public.city_roads;
delete from public.city_regions where id <> 'LEGACY';

-- ───────────── seed the circular city ─────────────
on conflict (id) do update set district = excluded.district, category = excluded.category, tier = excluded.tier, price = excluded.price,
  x = excluded.x, z = excluded.z, w = excluded.w, d = excluded.d, rot = excluded.rot, status = excluded.status, landmark = excluded.landmark, region = null;

on conflict (id) do update set kind = excluded.kind, x0 = excluded.x0, z0 = excluded.z0, x1 = excluded.x1, z1 = excluded.z1, w = excluded.w;

-- Pre-built buildings: J Enterprise + the ring around it (platform-owned; admins can reassign them).
on conflict (plot_id) do nothing;

-- ───────────── server-side geometry validation ─────────────
-- Oriented-box overlap (separating axis). Box axes: x = (cos a, -sin a), z = (sin a, cos a) – same as the app.
create or replace function public.obb_overlap(x1 double precision, z1 double precision, hw1 double precision, hd1 double precision, a1 double precision,
                                              x2 double precision, z2 double precision, hw2 double precision, hd2 double precision, a2 double precision, m double precision default 0)
returns boolean language plpgsql immutable as $$
declare ax double precision[] := array[cos(a1), -sin(a1), sin(a1), cos(a1), cos(a2), -sin(a2), sin(a2), cos(a2)];
        i int; nx double precision; nz double precision; d double precision; r1 double precision; r2 double precision;
begin
  for i in 0..3 loop
    nx := ax[i*2+1]; nz := ax[i*2+2];
    d := abs((x2 - x1) * nx + (z2 - z1) * nz);
    r1 := hw1 * abs(cos(a1) * nx - sin(a1) * nz) + hd1 * abs(sin(a1) * nx + cos(a1) * nz);
    r2 := hw2 * abs(cos(a2) * nx - sin(a2) * nz) + hd2 * abs(sin(a2) * nx + cos(a2) * nz);
    if d >= r1 + r2 + m - 0.000001 then return false; end if;
  end loop;
  return true;
end $$;

create or replace function public.city_plots_validate() returns trigger language plpgsql as $$
declare hit text; r record;
begin
  select c.id into hit from public.city_plots c where c.id <> new.id
    and public.obb_overlap(new.x, new.z, new.w / 2, new.d / 2, new.rot, c.x, c.z, c.w / 2, c.d / 2, c.rot, 0) limit 1;
  if hit is not null then raise exception 'Plot % overlaps plot %', new.id, hit; end if;
  for r in select * from public.city_roads where kind = 'seg' loop
    if public.obb_overlap(new.x, new.z, new.w / 2, new.d / 2, new.rot, (r.x0 + r.x1) / 2, (r.z0 + r.z1) / 2, sqrt((r.x1 - r.x0) ^ 2 + (r.z1 - r.z0) ^ 2) / 2, r.w / 2, atan2(-(r.z1 - r.z0), (r.x1 - r.x0)), 0) then
      raise exception 'Plot % overlaps road %', new.id, r.id;
    end if;
  end loop;
  return new;
end $$;
create trigger city_plots_validate before insert or update of x, z, w, d, rot on public.city_plots for each row execute function public.city_plots_validate();

create or replace function public.city_roads_validate() returns trigger language plpgsql as $$
declare hit text;
begin
  if new.kind = 'seg' then
    if (new.x0 = new.x1 and new.z0 = new.z1) then raise exception 'Road % has zero length', new.id; end if;
    select p.id into hit from public.city_plots p where public.obb_overlap(p.x, p.z, p.w / 2, p.d / 2, p.rot, (new.x0 + new.x1) / 2, (new.z0 + new.z1) / 2, sqrt((new.x1 - new.x0) ^ 2 + (new.z1 - new.z0) ^ 2) / 2, new.w / 2, atan2(-(new.z1 - new.z0), (new.x1 - new.x0)), 0) limit 1;
    if hit is not null then raise exception 'Road % overlaps plot %', new.id, hit; end if;
  end if;
  return new;
end $$;
create trigger city_roads_validate before insert or update on public.city_roads for each row execute function public.city_roads_validate();

-- Expansion: plots and roads are validated by the triggers above, so this only checks authorization and size.
create or replace function public.admin_expand_city(p_region jsonb, p_plots jsonb, p_roads jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare p jsonb; rd jsonb;
begin
  if not public.is_admin() then raise exception 'Not authorized' using errcode = '42501'; end if;
  if jsonb_array_length(p_plots) > 500 or jsonb_array_length(p_roads) > 100 then raise exception 'Expansion too large'; end if;
  for p in select * from jsonb_array_elements(p_plots) loop
      values (p->>'id', p_region->>'id', p->>'district', p->>'category', p->>'tier', (p->>'price')::int, (p->>'x')::numeric, (p->>'z')::numeric, (p->>'w')::numeric, (p->>'d')::numeric, (p->>'rot')::numeric, 'available');
  end loop;
  for rd in select * from jsonb_array_elements(p_roads) loop
  end loop;
end $$;
revoke all on function public.admin_expand_city(jsonb, jsonb, jsonb) from public;
grant execute on function public.admin_expand_city(jsonb, jsonb, jsonb) to authenticated;
